import { useFrame } from '@react-three/fiber'
import { useEffect, useRef } from 'react'
import * as THREE from 'three'
import type { LaserHandle, LaserOwner } from './types'

interface LaserProps {
  id: string
  owner: LaserOwner
  origin: THREE.Vector3
  direction: THREE.Vector3
  speed: number
  onExpired: (id: string) => void
  register: (handle: LaserHandle) => void
  unregister: (id: string) => void
}

export function Laser({ id, owner, origin, direction, speed, onExpired, register, unregister }: LaserProps) {
  const mesh = useRef<THREE.Mesh>(null)
  const group = useRef<THREE.Group>(null)
  const handle = useRef<LaserHandle>({
    id,
    owner,
    position: origin.clone(),
    alive: true,
  })
  const velocity = direction.clone().normalize().multiplyScalar(speed)

  useEffect(() => {
    register(handle.current)
    return () => unregister(id)
  }, [id, register, unregister])

  useFrame((_, delta) => {
    if (!group.current || !handle.current.alive) {
      onExpired(id)
      return
    }
    group.current.position.addScaledVector(velocity, delta)
    // Collision reads the projectile's world position, not the child mesh's local coordinates.
    group.current.getWorldPosition(handle.current.position)
    if (handle.current.position.z < -120 || handle.current.position.z > 14) {
      handle.current.alive = false
      onExpired(id)
    }
  })

  const color = owner === 'player' ? '#76f5ff' : '#ff685c'
  return (
    <group ref={group} position={origin}>
      <mesh ref={mesh}>
        <boxGeometry args={[0.08, 0.08, owner === 'player' ? 1.4 : 1.05]} />
        <meshBasicMaterial color={color} toneMapped={false} />
      </mesh>
      <pointLight color={color} intensity={owner === 'player' ? 3.4 : 2.2} distance={5.5} />
    </group>
  )
}

