import { useFrame } from '@react-three/fiber'
import { useMemo, useRef } from 'react'
import * as THREE from 'three'
import type { WorldState } from './types'

const VERTEX_SHADER = /* glsl */ `
  uniform float uTime;
  uniform float uScroll;
  varying float vHeight;
  varying vec2 vUv;

  float heightAt(vec2 p) {
    float canyon = sin(p.x * 0.075 + uScroll * 0.012) * 1.6;
    float ridge = sin(p.x * 0.21 + p.y * 0.035) * 0.42;
    float chop = sin(p.x * 0.8 + p.y * 0.15) * 0.12;
    return -1.6 + canyon + ridge + chop;
  }

  void main() {
    vUv = uv;
    vec3 displaced = position;
    displaced.z = heightAt(vec2(position.x, position.y));
    vHeight = displaced.z;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(displaced, 1.0);
  }
`

const FRAGMENT_SHADER = /* glsl */ `
  varying float vHeight;
  varying vec2 vUv;

  void main() {
    float gridX = smoothstep(0.46, 0.49, abs(fract(vUv.x * 22.0) - 0.5));
    float gridY = smoothstep(0.46, 0.49, abs(fract(vUv.y * 34.0) - 0.5));
    float grid = max(gridX, gridY);
    vec3 low = vec3(0.018, 0.10, 0.16);
    vec3 high = vec3(0.06, 0.34, 0.38);
    vec3 color = mix(low, high, clamp(vHeight * 0.17 + 0.3, 0.0, 1.0));
    color += vec3(0.02, 0.12, 0.12) * grid;
    gl_FragColor = vec4(color, 1.0);
  }
`

const TILE_LENGTH = 128
const TILE_COUNT = 3

export function Terrain({ world }: { world: WorldState }) {
  const tiles = useRef<(THREE.Mesh | null)[]>([])
  const uniforms = useMemo(
    () => ({ uTime: { value: 0 }, uScroll: { value: 0 } }),
    [],
  )

  useFrame(({ clock }) => {
    const cycle = Math.floor(world.distance / TILE_LENGTH)
    const offset = THREE.MathUtils.euclideanModulo(world.distance, TILE_LENGTH)
    uniforms.uTime.value = clock.elapsedTime
    uniforms.uScroll.value = world.distance
    // Reassign mesh slots as whole tiles pass the camera; this preserves a
    // contiguous, ordered rail instead of letting indices drift forward.
    tiles.current.forEach((tile, index) => {
      if (!tile) return
      const slot = THREE.MathUtils.euclideanModulo(index - cycle, TILE_COUNT)
      tile.position.z = -92 + slot * TILE_LENGTH + offset
    })
  })

  return (
    <group>
      {Array.from({ length: TILE_COUNT }, (_, index) => (
        <mesh
          key={index}
          ref={(mesh) => { tiles.current[index] = mesh }}
          rotation={[-Math.PI / 2, 0, 0]}
          position={[0, -3.5, -92 + index * TILE_LENGTH]}
          frustumCulled={false}
        >
          <planeGeometry args={[100, TILE_LENGTH, 36, 48]} />
          <shaderMaterial
            uniforms={uniforms}
            vertexShader={VERTEX_SHADER}
            fragmentShader={FRAGMENT_SHADER}
            side={THREE.DoubleSide}
          />
        </mesh>
      ))}

      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -3.15, -82]}>
        <planeGeometry args={[42, 400]} />
        <meshStandardMaterial color="#0b4b66" emissive="#031a2b" emissiveIntensity={0.7} roughness={0.8} />
      </mesh>

      <mesh position={[-18, 5, -105]} rotation={[0, 0, Math.PI / 2]}>
        <coneGeometry args={[8, 34, 5]} />
        <meshStandardMaterial color="#113a56" emissive="#082238" emissiveIntensity={0.6} flatShading />
      </mesh>
      <mesh position={[19, 7, -142]} rotation={[0, 0, -Math.PI / 2]}>
        <coneGeometry args={[10, 42, 5]} />
        <meshStandardMaterial color="#16445d" emissive="#082238" emissiveIntensity={0.6} flatShading />
      </mesh>
    </group>
  )
}

