import * as THREE from 'three'

/**
 * One deterministic difficulty curve for the whole mission. Progress is the
 * distance travelled over the 420m route, clamped to [0, 1]. Every multiplier
 * has a cap so late waves are demanding without becoming unavoidable.
 */
export const LEVEL_LENGTH = 420

export interface Difficulty {
  progress: number
  healthMultiplier: number
  fireIntervalMultiplier: number
  projectileSpeed: number
  aimLead: number
  accuracy: number
  waveDensity: number
  formationScale: number
}

export function normalizedLevelProgress(distance: number) {
  return THREE.MathUtils.clamp(distance / LEVEL_LENGTH, 0, 1)
}

export function getDifficulty(progress: number): Difficulty {
  const p = THREE.MathUtils.clamp(progress, 0, 1)
  return {
    progress: p,
    healthMultiplier: 1 + p * 0.9,
    fireIntervalMultiplier: 1 - p * 0.45,
    projectileSpeed: 42 + p * 21,
    aimLead: 0.15 + p * 0.85,
    accuracy: 0.34 + p * 0.6,
    waveDensity: 1 + p * 0.5,
    formationScale: 1 + p * 0.22,
  }
}

export function scaledHealth(baseHealth: number, difficulty: Difficulty) {
  return Math.max(1, Math.ceil(baseHealth * difficulty.healthMultiplier))
}

/** Deterministic formation expansion and density: no random wave spawns. */
export function buildWave(
  enemies: Array<{ variant: 'scout' | 'heavy' | 'turret' | 'carrier'; x: number; y: number; z: number; health: number; target?: 'lyra' | 'rook' | 'pip' }>,
  difficulty: Difficulty,
) {
  const result = enemies.map((enemy) => ({
    ...enemy,
    x: enemy.x * difficulty.formationScale,
    health: scaledHealth(enemy.health, difficulty),
  }))
  const extraCount = Math.max(0, Math.ceil((difficulty.waveDensity - 1) * enemies.length))
  for (let index = 0; index < extraCount; index += 1) {
    const source = enemies[index % enemies.length]
    if (source.variant === 'carrier') continue
    result.push({
      ...source,
      x: source.x * difficulty.formationScale + (index % 2 === 0 ? -2.4 : 2.4),
      y: source.y + (index % 2 === 0 ? 0.8 : -0.8),
      z: source.z - 7 - index * 3,
      health: scaledHealth(source.health, difficulty),
      target: undefined,
    })
  }
  return result
}

